{"content":"#!/usr/bin/env node
/**
 * Smoke test for dev/mocks/tchat-mock.mjs (TASK-009)
 *
 * 啟動 mock（子進程，隨機 port）→ 打契約 v0 互動 → 驗證 jsonl 落檔
 * → 驗證 ok / reject / down 三情境 → 讀 /__sent 結束。
 *
 * Usage: node .paaw/tmp/smoke-tchat-mock.mjs
 */
import { spawn } from "node:child_process";
import { mkdtempSync, rmSync } from "node:fs";
import { readFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

const PORT = 34_002;
const BASE = `http://localhost:${PORT}`;

const proc = spawn("node", ["dev/mocks/tchat-mock.mjs"], {
  env: { ...process.env, MOCK_TCHAT_PORT: String(PORT) },
  stdio: ["ignore", "pipe", "pipe"],
});

let failures = 0;
const check = (label, cond, extra = "") => {
  const mark = cond ? "PASS" : "FAIL";
  if (!cond) failures += 1;
  console.log(`  [${mark}] ${label}${extra ? ` — ${extra}` : ""}`);
};

async function waitForServer(timeoutMs = 5000) {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    try {
      const r = await fetch(`${BASE}/__scenario`);
      if (r.ok) return true;
    } catch { /* not up yet */ }
    if (proc.exitCode !== null) return false;
    await new Promise(r => setTimeout(r, 100));
  }
  return false;
}

const post = async (path, body) => {
  const r = await fetch(`${BASE}${path}`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
  let data = null;
  try { data = await r.json(); } catch { /* down scenario has no response */ }
  return { status: r.status, data };
};

try {
  const up = await waitForServer();
  check("mock server starts on port", up);
  if (!up) throw new Error("server never came up");

  // ── scenario: ok ──
  console.log("\n── scenario: ok（契約 v0 正常路徑）──");
  let r = await post("/__scenario", { name: "ok" });
  check("switch to ok", r.status === 200 && r.data.scenario === "ok");

  r = await post("/api/messages", { targetType: "channel", targetId: "ops", text: "🚨 CPU 95% on api-3" });
  check("send → 200 + ok:true", r.status === 200 && r.data?.ok === true, `messageId=${r.data?.messageId}`);
  check("messageId is string", typeof r.data?.messageId === "string");

  r = await post("/api/messages", { targetType: "user", targetId: "alice", text: "patrol all-clear" });
  check("second send → 200", r.status === 200 && r.data?.ok === true);

  // 驗證錯誤格式（契約 v0：驗證失敗 → 400 + {ok:false,error}）
  r = await post("/api/messages", { targetType: "group", targetId: "x", text: "bad type" });
  check("invalid targetType → 400 + ok:false", r.status === 400 && r.data?.ok === false && !!r.data?.error);

  // jsonl 落檔驗證
  let sent = await (await fetch(`${BASE}/__sent`)).json();
  check("jsonl has 2 messages (invalid one not logged)", sent.lines === 2, `lines=${sent.lines}`);
  check(
    "first message shape {ts,targetType,targetId,text}",
    sent.messages[0].targetType === "channel" && sent.messages[0].targetId === "ops" && sent.messages[0].text.includes("CPU") && !!sent.messages[0].ts
  );

  // ── reset ──
  console.log("\n── reset ──");
  r = await post("/__reset", {});
  check("POST /__reset → ok", r.status === 200 && r.data?.ok === true);
  sent = await (await fetch(`${BASE}/__sent`)).json();
  check("sent log cleared", sent.lines === 0);

  // ── scenario: reject ──
  console.log("\n── scenario: reject（公司 API 拒絕 → notifyError 路徑）──");
  r = await post("/__scenario", { name: "reject" });
  check("switch to reject", r.status === 200 && r.data.scenario === "reject");

  r = await post("/api/messages", { targetType: "channel", targetId: "ops", text: "should fail" });
  check("send → 403 + ok:false + error", r.status === 403 && r.data?.ok === false && !!r.data?.error);
  sent = await (await fetch(`${BASE}/__sent`)).json();
  check("rejected message NOT logged", sent.lines === 0, `lines=${sent.lines}`);

  // ── scenario: down ──
  console.log("\n── scenario: down（斷線 → client timeout 路徑）──");
  r = await post("/__scenario", { name: "down" });
  check("switch to down", r.status === 200 && r.data.scenario === "down");

  const start = Date.now();
  const origFetch = globalThis.fetch;
  // 直接用短 timeout 打：client.mjs 的 AbortSignal.timeout 語意
  const ctl = new AbortController();
  const timer = setTimeout(() => ctl.abort(), 800);
  try {
    const resp = await fetch(`${BASE}/api/messages`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ targetType: "user", targetId: "bob", text: "gone" }),
      signal: ctl.signal,
    });
    check("down scenario yields no response (should not reach here)", false, `unexpected status ${resp.status}`);
  } catch (err) {
    check("down scenario: request aborts (no response)", /abort/i.test(err?.name + err?.message), err?.name);
  } finally {
    clearTimeout(timer);
  }
  void origFetch;
  console.log(`  (down wait: ${Date.now() - start}ms)`);

  sent = await (await fetch(`${BASE}/__sent`)).json();
  check("nothing logged during down", sent.lines === 0);

  // ── unknown scenario ──
  console.log("\n── unknown scenario guard ──");
  r = await post("/__scenario", { name: "nope" });
  check("unknown scenario → 400 with valid list", r.status === 400 && Array.isArray(r.data?.valid));

  console.log(`\n${failures === 0 ? "✅ ALL PASS" : `❌ ${failures} FAILURES`}`);
  process.exitCode = failures === 0 ? 0 : 1;
} catch (err) {
  console.error(`\n💥 smoke aborted: ${err.message}`);
  process.exitCode = 1;
} finally {
  proc.kill("SIGKILL");
}
