  if (!isFailure && policy !== "always") {
    console.log(`[scheduler] notify skipped by policy (${policy}) agent=${agent.id}`);
    return { sent: false, error: null, skippedByPolicy: true, ...(agentNotified ? { notifiedByAgent: true } : {}) };
