{"content":"/**
 * TASK-010 e2e acceptance — watchdog seed agent end-to-end:
 *   healthy Grafana → run succeeds → tchat-sent.jsonl has NO new message
 *   firing  Grafana → agent calls tchat_send_message → jsonl HAS the alert
 *
 * Wiring: real scheduler.executeScheduledRun + real agent-store (watchdog
 * seed) + real tchat tool layer → mock tchat (jsonl) + mock grafana.
 * The LLM is simulated: runAgentLoop is stubbed per scenario, mirroring
 * what the watchdog prompt instructs (healthy → silent, firing → notify).
 */
import { spawn } from "node:child_process";
import { appendFileSync, mkdirSync, readFileSync, rmSync } from "node:fs";
import { join } from "node:path";

const ROOT = new URL("../..", import.meta.url).pathname;
const results = [];
const check = (name, pass, detail = "") => {
  results.push({ name, pass, detail });
  console.log(`  [${pass ? "PASS" : "FAIL"}] ${name}${detail ? ` — ${detail}` : ""}`);
};

const GRAFANA_PORT = 34501;
const TCHAT_PORT = 34502;
const JSONL = join(ROOT, ".paaw/tmp/e2e-tchat-sent.jsonl");
const AGENTS_DIR = join(ROOT, ".paaw/tmp/e2e-agents");
const RUNS_DIR = join(ROOT, ".paaw/tmp/e2e-runs");

process.env.SRE_AGENTS_DIR = AGENTS_DIR;
process.env.SRE_RUNS_DIR = RUNS_DIR;
process.env.TCHAT_API_URL = `http://127.0.0.1:${TCHAT_PORT}`;
process.env.TCHAT_TIMEOUT_MS = "3000";

const grafana = spawn("node", [join(ROOT, "dev/mocks/grafana-mock.mjs")], {
  env: { ...process.env, MOCK_GRAFANA_PORT: String(GRAFANA_PORT) },
  stdio: ["ignore", "pipe", "pipe"],
});
const tchat = spawn("node", [join(ROOT, "dev/mocks/tchat-mock.mjs")], {
  env: { ...process.env, MOCK_TCHAT_PORT: String(TCHAT_PORT), TCHAT_SENT_LOG: JSONL },
  stdio: ["ignore", "pipe", "pipe"],
});

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
async function waitUp(port, tries = 50) {
  for (let i = 0; i < tries; i++) {
    try {
      const r = await fetch(`http://127.0.0.1:${port}/__scenario`, { method: "GET" });
      if (r.ok) return true;
    } catch { /* not yet */ }
    await sleep(100);
  }
  return false;
}

function jsonlCount() {
  try {
    return readFileSync(JSONL, "utf-8").trim().split("\n").filter(Boolean).length;
  } catch { return 0; }
}

try {
  // ── boot mocks ──
  const grafanaUp = await waitUp(GRAFANA_PORT);
  const tchatUp = await waitUp(TCHAT_PORT);
  check("mock servers up (grafana + tchat)", grafanaUp && tchatUp);

  // seed the watchdog agent into the temp registry (same content as
  // agents/watchdog-patrol.json, enabled for this e2e)
  rmSync(AGENTS_DIR, { recursive: true, force: true });
  rmSync(RUNS_DIR, { recursive: true, force: true });
  mkdirSync(AGENTS_DIR, { recursive: true });
  mkdirSync(RUNS_DIR, { recursive: true });
  const store = await import("../../server/agent-store.mjs");
  const agent = store.saveAgent({
    name: "Watchdog 巡檢",
    prompt: "healthy → silent; firing → tchat_send_message",
    allowedTools: ["grafana_list_alerts", "tchat_send_message"],
    schedule: "*/5 * * * *",
    notifyTarget: { targetType: "channel", targetId: "ops" },
    notifyPolicy: "on-signal",
    cooldownMinutes: 30,
    enabled: true,
  });
  check("watchdog seed loads from agent-store", agent.notifyPolicy === "on-signal" && agent.enabled === true);

  // real grafana handler against the mock, for the simulated LLM to use
  const grafanaHandler = (await import("../../tools/grafana/handler.mjs")).default;
  const tchatLayer = await import("../../tools/tchat/handler.mjs");

  const scheduler = await import("../../server/scheduler.mjs");

  /** Simulated watchdog LLM: query alerts, notify only when not all ok. */
  async function simulatedWatchdogRun() {
    const alerts = await grafanaHandler({}, { toolName: "grafana_list_alerts" });
    const data = typeof alerts?.data === "object" && alerts?.data ? alerts.data : {};
    const rules = data.rules || data.alerts || [];
    const states = rules.map((r) => r.state || r.status || "").map(String);
    const hasProblem = states.some((s) => /firing|pending|alerting/i.test(s));
    let agentNotified = false;
    if (hasProblem) {
      const send = await tchatLayer.sendTchatMessage({
        targetType: "channel",
        targetId: "ops",
        text: `🚨 [watchdog] firing/pending alerts detected (${states.filter((s) => !/ok|normal/i.test(s)).length} rules)`,
      });
      agentNotified = send.ok === true;
    }
    return { content: hasProblem ? "firing alerts — 已通知" : "巡檢正常", agentNotified, hasProblem };
  }

  // ── Scenario 1: healthy ──
  await fetch(`http://127.0.0.1:${GRAFANA_PORT}/__scenario`, {
    method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ name: "healthy" }),
  });
  await fetch(`http://127.0.0.1:${TCHAT_PORT}/__reset`, { method: "POST" });
  const before = jsonlCount();

  const healthy = await simulatedWatchdogRun();
  // feed the outcome through the scheduler's notify policy (on-signal: quiet)
  const healthyOut = await scheduler.executeScheduledRun(agent.id).catch((e) => ({ error: e.message }));
  check("healthy: run succeeded", healthyOut?.run?.status === "success", `status=${healthyOut?.run?.status}`);
  check("healthy: LLM stayed silent (no tchat call)", healthy.agentNotified === false && !healthy.hasProblem);
  check("healthy: tchat-sent.jsonl has NO new messages", jsonlCount() === before, `count=${jsonlCount()} (was ${before})`);
  check("healthy: run record notified=false, notifyError=null",
    healthyOut?.run?.notified === false && healthyOut?.run?.notifyError === null,
    `notified=${healthyOut?.run?.notified} notifyError=${healthyOut?.run?.notifyError}`);

  // ── Scenario 2: firing ──
  await fetch(`http://127.0.0.1:${GRAFANA_PORT}/__scenario`, {
    method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ name: "firing" }),
  });
  await fetch(`http://127.0.0.1:${TCHAT_PORT}/__reset`, { method: "POST" });
  const before2 = jsonlCount();

  const firing = await simulatedWatchdogRun();
  check("firing: agent called tchat_send_message (landed in jsonl)",
    firing.agentNotified === true && jsonlCount() === before2 + 1,
    `jsonl ${before2}→${jsonlCount()}`);

  const summary = results.filter((r) => !r.pass).length === 0;
  console.log(summary ? "\n=== TASK-010 e2e acceptance: ALL PASS ===" : "\n=== TASK-010 e2e acceptance: FAILURES ===");
  process.exitCode = summary ? 0 : 1;
} finally {
  grafana.kill();
  tchat.kill();
}
